<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';
import {request} from './workbench-api';
const props=defineProps({documentId:{type:String,required:true}});
const revisions=ref([]),from=ref(''),to=ref(''),result=ref(null),page=ref(1),busy=ref(false),error=ref(''),mode=ref('parallel');let seq=0;
const names={added:'新增',removed:'移除',modified:'修改',unchanged:'未变'};
async function compare(){if(!from.value||!to.value)return;const token=++seq;busy.value=true;result.value=null;error.value='';try{const q=new URLSearchParams({from_revision:from.value,to_revision:to.value,page:String(page.value),page_size:'10'});const r=await request(`/documents/${props.documentId}/diff?${q}`);if(token===seq)result.value=r;}catch(e){if(token===seq)error.value=e.message;}finally{if(token===seq)busy.value=false;}}
watch(()=>props.documentId,async id=>{const token=++seq;revisions.value=[];from.value='';to.value='';result.value=null;error.value='';page.value=1;if(!id)return;try{const r=await request(`/documents/${id}/revisions`);if(token!==seq)return;revisions.value=r.items;to.value=r.items[0]?.revision_id||'';from.value=r.items[1]?.revision_id||to.value;await compare();}catch(e){if(token===seq)error.value=e.message;}},{immediate:true});
onBeforeUnmount(()=>{seq++;});
</script>
<template><section class="wb-version-diff"><h4>版本差异</h4><p>对比保存的正文修订；原件、修正记录和审核历史分别保留。</p><div class="choices"><label>旧版本<select v-model="from" aria-label="比较旧版本" @change="page=1;compare()"><option v-for="r in revisions" :key="r.revision_id" :value="r.revision_id">{{r.revision_id}} · {{r.operation}}</option></select></label><label>新版本<select v-model="to" aria-label="比较新版本" @change="page=1;compare()"><option v-for="r in revisions" :key="r.revision_id" :value="r.revision_id">{{r.revision_id}} · {{r.operation}}</option></select></label></div><p v-if="busy">正在比较…</p><p v-if="error" role="alert" class="wb-error-text">{{error}}</p><p v-if="!busy&&!revisions.length">暂无正文修订。</p><template v-if="result"><div class="wb-chips"><span v-for="(n,k) in result.counts" :key="k">{{names[k]}} {{n}}</span></div><p v-if="result.single_revision&&revisions.length===1">当前只有这一份可比较修订。</p><p v-else-if="from===to">当前选择了同一修订，可切换另一版本比较。</p><label>显示方式<select v-model="mode" aria-label="版本差异显示方式"><option value="parallel">并排正文</option><option value="lines">逐行差异</option></select></label><article v-for="(change,i) in result.items" :key="i" class="change"><strong>{{names[change.kind]}} · {{change.after?.chunk_id||change.before?.chunk_id}}</strong><div v-if="mode==='parallel'" class="parallel"><div><small>旧版本</small><pre>{{change.before?.content??'〔此版本无此块〕'}}</pre><small v-if="change.before?.content_truncated">正文较长，此处显示前 8,000 字符。</small></div><div><small>新版本</small><pre>{{change.after?.content??'〔此版本无此块〕'}}</pre><small v-if="change.after?.content_truncated">正文较长，此处显示前 8,000 字符。</small></div></div><pre v-else>{{change.diff||'正文相同，启停、页码或块属性发生变化。'}}</pre><p v-if="change.diff_truncated">逐行差异较长，显示前 12,000 字符。</p></article><p v-if="!result.total">两份修订的正文和块属性相同。</p><div v-if="result.total>10" class="wb-between wb-pagination"><button class="wb-button tiny" :disabled="busy||page===1" @click="page--;compare()">差异上一页</button><span>{{page}} / {{Math.ceil(result.total/10)}}</span><button class="wb-button tiny" :disabled="busy||page*10>=result.total" @click="page++;compare()">差异下一页</button></div></template></section></template>
<style scoped>.choices,.parallel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.choices label{min-width:0}select{width:100%;max-width:100%}.change{padding:12px;border:1px solid #d5dce4;border-radius:8px;margin:12px 0;overflow-wrap:anywhere}.parallel>div{min-width:0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto;background:#f4f7fa;padding:10px;font-size:12px}small{overflow-wrap:anywhere}@media(max-width:750px){.choices,.parallel{grid-template-columns:minmax(0,1fr)}}</style>
